using System;
using System.Collections.Generic;
using System.Linq;
namespace MK.Verification {
 public static class HumanizationRegression {
  static int checks;static void Assert(bool value,string label){checks++;if(!value)throw new Exception("Humanization: "+label);}
  static bool Up(Native.INPUT e){return e.type==1&&(e.U.ki.dwFlags&2)!=0||e.type==0&&(e.U.mi.dwFlags&4)!=0;}
  public static string Run(){
   checks=0;using(var timer=new Native.InputTimer()){timer.Slice(1);timer.Slice(0);try{timer.Slice(11);Assert(false,"unbounded timer slice");}catch(ArgumentOutOfRangeException){Assert(true,"timer slices bounded");}timer.Dispose();timer.Dispose();try{timer.Slice(1);Assert(false,"disposed timer reused");}catch(ObjectDisposedException){Assert(true,"timer disposed");}}Assert(!Server.ShouldHideIdle(true,true,true,20000),"long active input retains its indicator");Assert(Server.ShouldHideIdle(true,false,true,11000),"idle ready state may hide");Assert(!Server.ShouldHideIdle(false,false,true,20000),"closed state does not schedule late idle UI");IntPtr layout=Native.GetKeyboardLayout(0);var typed=new Humanizer(42).Text("aA1?中😀","auto","natural",null,layout);
   Assert(typed.Units.Count==6,"Unicode codepoints are not split");
   var ascii=typed.Units.Take(4).SelectMany(u=>u.Steps).SelectMany(s=>s.Inputs).ToArray();Assert(ascii.All(e=>e.type==1&&(e.U.ki.dwFlags&4)==0),"auto ASCII uses mapped keys on every target");
   Assert(ascii.Where(e=>e.U.ki.wVk!=16).All(e=>(e.U.ki.dwFlags&8)!=0&&e.U.ki.wScan!=0),"ASCII main keys carry real scan code fields");
   var scanHeld=new OwnedInputs();var original=ascii.First(e=>e.U.ki.wVk!=16&&!Up(e));scanHeld.Record(new[]{original},1);scanHeld.Release(e=>{Assert(e.U.ki.wScan==original.U.ki.wScan&&(e.U.ki.dwFlags&8)!=0&&Up(e),"cleanup preserves original scan and flags");return 1;},key=>false);
   Assert(typed.Units[4].Steps.SelectMany(s=>s.Inputs).All(e=>(e.U.ki.dwFlags&4)!=0),"non ASCII stays Unicode");Assert(typed.Units[5].Steps.Count==1&&typed.Units[5].Steps[0].Inputs.Length==4,"surrogates atomic");
   Assert(typed.Units.SelectMany(u=>u.Steps).SelectMany(s=>s.Inputs).All(e=>e.U.ki.dwExtraInfo.ToUInt64()==(ulong)Native.Marker),"injection marker unchanged");
   var unicode=new Humanizer(3).Text("abc","unicode","off",null,layout);Assert(unicode.Units.SelectMany(u=>u.Steps).SelectMany(s=>s.Inputs).All(e=>(e.U.ki.dwFlags&4)!=0),"explicit Unicode mode retained");
   try{new Humanizer(0).Text("a中","scancode","natural",null,layout);Assert(false,"unsupported accepted");}catch(Failure e){Assert(e.Code=="UNSUPPORTED_INPUT","scancode entire request rejected");}
   var gaps=new List<double>();for(int seed=0;seed<120;seed++){var plan=new Humanizer(seed).Text(new String('a',64),"auto","natural",null,layout);double at=0,prior=-1;foreach(var unit in plan.Units)foreach(var step in unit.Steps){at+=step.DelayBeforeMs;foreach(var input in step.Inputs)if(input.U.ki.wVk==65&&!Up(input)){if(prior>=0)gaps.Add(at-prior);prior=at;}}}
   var sorted=gaps.OrderBy(x=>x).ToArray();double median=sorted[sorted.Length/2],mean=gaps.Average(),sd=Math.Sqrt(gaps.Select(x=>(x-mean)*(x-mean)).Average()),p95=sorted[(int)(sorted.Length*.95)],p99=sorted[(int)(sorted.Length*.99)];Assert(median>=110&&median<=130,"natural median 110-130ms");Assert(p95>=400&&p95<=900&&p99>=800,"explicit heavy tail");Assert(1000/mean>=4&&1000/mean<=8,"planned average 4-8 chars per second");
   var clustered=new Humanizer(91).Text(new String('a',64),"auto","natural",null,layout);var intervals=new List<int>();int previousHold=0;for(int i=0;i<clustered.Units.Count;i++){var unit=clustered.Units[i];if(i>0)intervals.Add(previousHold+unit.Steps[0].DelayBeforeMs);previousHold=unit.Steps.Skip(1).Sum(s=>s.DelayBeforeMs);}Assert(intervals.Count(x=>x>=350)>=7&&intervals.Count(x=>x<200)>=35,"burst and pause modes both present");
   var plain=new Humanizer(91).Text("aa","unicode","natural",null,layout);foreach(string context in new[]{" a",".a","aA"}){var modulated=new Humanizer(91).Text(context,"unicode","natural",null,layout);Assert(modulated.DelayMs>plain.DelayMs,"context adds a bounded pause");}
   var off=new Humanizer(4).Text("PageFaultTest","auto","off",0,layout);Assert(off.DelayMs==0&&off.Units.All(u=>u.Steps.Count==1),"maxSpeed deterministic");
   var combo=new Humanizer(8).Key("Ctrl+A","natural");Assert(combo.Units[0].Steps.Count==4,"combo events separated");Assert(combo.Units[0].Steps[1].DelayBeforeMs>=10&&combo.Units[0].Steps[1].DelayBeforeMs<=40,"modifier lead");
   var bounds=new Native.RECT{Left=-1920,Top=-100,Right=3840,Bottom=2160};var target=new Native.RECT{Left=800,Top=300,Right=820,Bottom=320};int over=0;var holds=new HashSet<int>();int longest=0;
   for(int seed=0;seed<100;seed++){var start=new Native.POINT{X=-800,Y=100};var expected=new Native.POINT{X=810,Y=310};var motion=new Humanizer(seed).MovePath(start,expected,bounds,target,"natural",true);if(motion.Overshoot)over++;holds.Add(motion.HoldMs);longest=Math.Max(longest,motion.Frames.Count);Assert(motion.Frames.Count>=40&&motion.Frames.Count<=90,"bounded mouse frames");Assert(motion.DelayMs-motion.HoldMs>=600&&motion.DelayMs-motion.HoldMs<=1600,"movement duration excludes click hold");Assert(motion.Frames.Sum(f=>f.DelayBeforeMs)==motion.DelayMs-motion.HoldMs,"deadlines match the complete motion budget");Assert(motion.HoldMs>=60&&motion.HoldMs<=120,"mouse hold");Assert(Math.Abs(motion.Target.X-expected.X)<=2&&Math.Abs(motion.Target.Y-expected.Y)<=2,"safe endpoint jitter");var prior=start;foreach(var frame in motion.Frames){Assert(frame.Point.X>=bounds.Left&&frame.Point.X<bounds.Right&&frame.Point.Y>=bounds.Top&&frame.Point.Y<bounds.Bottom,"virtual bounds");prior=frame.Point;}Assert(prior.X==motion.Target.X&&prior.Y==motion.Target.Y,"exact planned endpoint");}
   Assert(over>=15&&over<=50&&holds.Count>10,"varied holds and bounded overshoot probability");
   var representative=new Humanizer(6).MovePath(new Native.POINT{X=500,Y=310},new Native.POINT{X=810,Y=310},bounds,target,"natural",false);var steps=new List<double>();var prev=new Native.POINT{X=500,Y=310};foreach(var frame in representative.Frames){steps.Add(Math.Sqrt(Math.Pow(frame.Point.X-prev.X,2)+Math.Pow(frame.Point.Y-prev.Y,2)));prev=frame.Point;}steps.Sort();Assert(representative.Frames.Count>=40&&representative.Frames.Count<=90&&steps[steps.Count/2]>=3&&steps[steps.Count/2]<=8,"representative 310px path density");
   long clock=0;int emitted=0;Humanizer.RunMotion(representative,p=>{emitted++;clock+=3;},ms=>clock+=ms,()=>clock+=2,()=>clock);Assert(emitted==representative.Frames.Count&&clock<=representative.DelayMs-representative.HoldMs+10,"deadlines absorb validation and send overhead");
   clock=0;emitted=0;Humanizer.RunMotion(representative,p=>{emitted++;clock+=100;},ms=>clock+=ms,()=>{},()=>clock);Assert(emitted<representative.Frames.Count,"late frames are not replayed in a burst");
   for(int stop=0;stop<representative.Frames.Count;stop++){clock=0;emitted=0;try{Humanizer.RunMotion(representative,p=>{Assert(emitted<stop,"no motion after cancellation");emitted++;},ms=>clock+=ms,()=>{if(emitted==stop)throw new Failure("USER_STOPPED");},()=>clock);Assert(false,"motion cancellation ignored");}catch(Failure e){Assert(e.Code=="USER_STOPPED"&&emitted==stop,"each motion boundary is cancellable");}}
   var immediate=new Humanizer(6).MovePath(new Native.POINT{X=500,Y=310},new Native.POINT{X=810,Y=310},bounds,target,"off",true);Assert(immediate.Frames.Count==1&&immediate.DelayMs==0&&immediate.HoldMs==0&&immediate.Target.X==810,"maxSpeed skips motion randomness and holds");
   var point=new Native.POINT{X=810,Y=310};var exact=new Humanizer(1).MovePath(point,point,bounds,target,"natural",false);Assert(exact.Target.X==point.X&&exact.Target.Y==point.Y,"pixel coordinates are not jittered blindly");
   try{new Humanizer(1).Text(new String('a',16000),"auto","natural",null,layout);Assert(false,"budget accepted");}catch(Failure e){Assert(e.Code=="HUMANIZE_BUDGET_EXCEEDED"&&e.Execution=="not_sent","long slow text rejected before input");}
   // Fail at every scheduled boundary, then run the real ownership cleanup with an inert sink.
   for(int fail=0;fail<4;fail++){var owned=new OwnedInputs();var sent=new List<Native.INPUT>();int step=0;try{Humanizer.Run(combo.Units[0],events=>{if(step++==fail)throw new Failure("USER_STOPPED");owned.Record(events,events.Length);sent.AddRange(events);},ms=>{},()=>{});}catch(Failure){}finally{owned.Release(e=>{Assert(Up(e),"cleanup only releases owned events");sent.Add(e);return 1;},key=>false);}Assert(owned.Count==0,"no stuck modifiers after cancellation");}
   var mouse=new OwnedInputs();mouse.Record(new[]{Native.Mouse(2)},1);Assert(mouse.OwnsVirtual(1),"own held button is not USER_BUSY");int releases=0;mouse.Release(e=>{releases++;Assert((e.U.mi.dwFlags&4)!=0,"mouse release");return 1;},key=>false);Assert(releases==1&&mouse.Count==0,"held click released on failure");
   mouse.Record(new[]{Native.Mouse(2)},1);mouse.Release(e=>{Assert(false,"released physical button");return 1;},key=>key==1);Assert(mouse.Count==0,"physical takeover does not release user input");
   var broken=new OwnedInputs();broken.Record(new[]{Native.Key(16,false),Native.Key(65,false)},2);int attempted=0;try{broken.Release(e=>{attempted++;return e.U.ki.wVk==16?0u:1u;},key=>false);Assert(false,"cleanup failure accepted");}catch(Failure e){Assert(e.Code=="CONTROL_CLOSE_FAILED"&&attempted==2&&broken.Count==1,"partial cleanup remains unconfirmed and tries remaining keys");}broken.Release(e=>1,key=>false);Assert(broken.Count==0,"cleanup retry sends only releases");
   return new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(Native.D("ok",true,"mode","planner-and-inert-sink","assertions",checks,"checkedCaseIds",new[]{"HUM-02","HUM-03","HUM-04","HUM-05","HUM-06"},"plannedMedianMs",median,"plannedP95Ms",p95,"plannedP99Ms",p99,"plannedSdMs",Math.Round(sd,2),"plannedCharsPerSecond",Math.Round(1000/mean,2),"maximumMotionFrames",longest,"desktopObserved",false,"inputSent",false,"physicalProbe","NOT_RUN"));
  }
 }
}
